const neuroPairs=[{"trans":"«Necesito que me confirmes hoy mismo»","func":"«¿Qué pasa exactamente si te confirmo el jueves?»","opts":["«¿Qué pasa exactamente si te confirmo el jueves?»","«Es que hoy no puedo, tengo mucho trabajo»","«Está bien, dame diez minutos»","«¿Por qué siempre con prisas?»"]},{"trans":"«Quedan dos cupos»","func":"«Mándame por escrito hasta cuándo dura»","opts":["«Mándame por escrito hasta cuándo dura»","«¿Y si me guardas uno?»","«Entonces lo tomo ya»","«No te creo»"]},{"trans":"«O el paquete completo o no podemos»","func":"«¿Cuánto cuesta solo la impresión?»","opts":["«¿Cuánto cuesta solo la impresión?»","«Déjame ver si consigo el dinero»","«Está bien, el paquete»","«Entonces no hay trato»"]},{"trans":"«Esto ya lo aprobó la Secretaría»","func":"«Perfecto, pásame el documento y lo leo esta semana»","opts":["«Perfecto, pásame el documento y lo leo esta semana»","«¿Y quién lo aprobó exactamente?»","«Si está aprobado, adelante»","«Eso no puede ser verdad»"]},{"trans":"«Vamos a votarlo aquí mismo, delante de todos»","func":"«Les mando la respuesta el lunes por escrito»","opts":["«Les mando la respuesta el lunes por escrito»","«Prefiero no opinar»","«Voten ustedes, me da igual»","«Está bien, que sea rápido»"]}];
