const enfermedadData=[{"disease":"Firmó el viernes a las cinco para no alargar la reunión","characteristic":"Decidió con público y con prisa, que son dos tácticas a la vez","opts":["Decidió con público y con prisa, que son dos tácticas a la vez","No sabía lo que firmaba","El trato era malo desde el principio","Le faltó carácter"]},{"disease":"Mandó la propuesta de madrugada y puso un precio equivocado","characteristic":"Aceptó un plazo que nadie justificó y perdió el tiempo de revisarla","opts":["Aceptó un plazo que nadie justificó y perdió el tiempo de revisarla","Calculó mal la suma","La propuesta era difícil","Le faltó una plantilla"]},{"disease":"Compró la herramienta porque el descuento se acababa esa noche","characteristic":"No estaba en la lista de lo que hacía falta antes de aparecer la oferta","opts":["No estaba en la lista de lo que hacía falta antes de aparecer la oferta","La herramienta era mala","El descuento era falso","Se gastó más de la cuenta"]},{"disease":"Aceptó dar el material del año gratis a un centro amigo","characteristic":"Confundió devolver un favor con aceptar una deuda sin fin","opts":["Confundió devolver un favor con aceptar una deuda sin fin","No sabía decir que no","El amigo se aprovechó","El material no valía nada"]},{"disease":"Cedió a la quinta vez que se lo pidieron, sin razones nuevas","characteristic":"Cedió de cansancio: el desgaste no espera argumentos, espera un día malo","opts":["Cedió de cansancio: el desgaste no espera argumentos, espera un día malo","Al final lo convencieron","Se dio cuenta de que tenía razón","Ya no tenía excusas"]},{"disease":"Aprobó el paquete entero por quedarse con una sola parte","characteristic":"No preguntó cuánto costaba esa parte por separado","opts":["No preguntó cuánto costaba esa parte por separado","El paquete estaba bien de precio","Necesitaba las tres cosas","No había alternativa"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

